/// Rust to JS, one function per schema type, because the Rust type does not say which: a `Vec<u8>` is a string or an array of numbers.
pub mod to_js {
    use super::*;

    macro_rules! number {
        ($($name:ident: $t:ty => $f:expr;)*) => {$(
            #[inline(always)]
            pub fn $name<'a>(_: &JsHeap<'a>, value: $t) -> Result<'a, JsLocal<'a>> {
                Ok(JsLocal::from_raw($f(value)))
            }
        )*};
    }
    number! {
        bool: bool => JSValue::from;
        u8: u8 => |n| JSValue::js_number_from_int32(i32::from(n));
        u16: u16 => |n| JSValue::js_number_from_int32(i32::from(n));
        i32: i32 => JSValue::js_number_from_int32;
        u32: u32 => |n| JSValue::js_number_from_uint64(u64::from(n));
        u64: u64 => JSValue::js_number_from_uint64;
        usize: usize => |n| JSValue::js_number_from_uint64(n as u64);
        f64: f64 => |n| JSValue::js_number(JSValue::purify_nan(n));
    }

    #[inline]
    pub fn u64_as_bigint<'a>(heap: &JsHeap<'a>, value: u64) -> Result<'a, JsLocal<'a>> {
        JsLocal::from_js_result(JSValue::from_uint64_no_truncate(
            heap.global_object(),
            value,
        ))
    }

    #[inline]
    pub fn date<'a>(heap: &JsHeap<'a>, time_value: f64) -> Result<'a, JsLocal<'a>> {
        let date = JSValue::from_date_number(heap.global_object(), JSValue::purify_nan(time_value));
        Ok(JsLocal::from_raw(date))
    }

    #[inline(always)]
    pub fn undefined<'a>(_: &JsHeap<'a>, (): ()) -> Result<'a, JsLocal<'a>> {
        Ok(JsLocal::UNDEFINED)
    }

    /// A body may also return a plain [`JSValue`]: it goes straight back to JSC.
    pub trait Any<'a> {
        fn into_value(self, heap: &JsHeap<'a>) -> JsLocal<'a>;
    }
    impl<'a, T> Any<'a> for JsLocal<'a, T> {
        #[inline(always)]
        fn into_value(self, _: &JsHeap<'a>) -> JsLocal<'a> {
            self.as_value()
        }
    }
    impl<'a, T> Any<'a> for JsWrapper<'a, T> {
        #[inline(always)]
        fn into_value(self, _: &JsHeap<'a>) -> JsLocal<'a> {
            self.as_value().as_value()
        }
    }
    impl<'a> Any<'a> for JSValue {
        #[inline(always)]
        fn into_value(self, heap: &JsHeap<'a>) -> JsLocal<'a> {
            // A function of the older API returns the empty value after it threw.
            debug_assert!(!self.is_empty() || heap.exception_presence_matches(true));
            JsLocal::from_raw(self)
        }
    }

    #[inline(always)]
    pub fn any<'a>(heap: &JsHeap<'a>, value: impl Any<'a>) -> Result<'a, JsLocal<'a>> {
        Ok(value.into_value(heap))
    }

    #[inline(always)]
    pub fn utf8<'a>(heap: &JsHeap<'a>, value: impl AsRef<[u8]>) -> Result<'a, JsLocal<'a>> {
        heap.create_utf8_string(value.as_ref())
            .map(JsLocal::as_value)
    }

    #[inline]
    pub fn string<'a>(heap: &JsHeap<'a>, value: bun_core::String) -> Result<'a, JsLocal<'a>> {
        JsLocal::from_js_result(crate::StringJsc::into_js(value, heap.global_object()))
    }

    #[inline]
    pub fn string_array<'a>(
        heap: &JsHeap<'a>,
        strings: impl AsRef<[bun_core::String]>,
    ) -> Result<'a, JsLocal<'a>> {
        JsLocal::from_js_result(crate::bun_string_jsc::to_js_array(
            heap.global_object(),
            strings.as_ref(),
        ))
    }

    #[inline]
    pub fn array<'a, I: IntoIterator>(
        heap: &JsHeap<'a>,
        items: I,
        convert: impl FnMut(&JsHeap<'a>, I::Item) -> Result<'a, JsLocal<'a>>,
    ) -> Result<'a, JsLocal<'a>> {
        heap.create_array(items, convert).map(JsLocal::as_value)
    }

    /// A key that comes again keeps its place and takes the new value. The inline room is the upper `size_hint`.
    #[inline]
    pub fn record<'a, K: AsRef<[u8]>, V>(
        heap: &JsHeap<'a>,
        entries: impl IntoIterator<Item = (K, V)>,
        mut convert: impl FnMut(&JsHeap<'a>, V) -> Result<'a, JsLocal<'a>>,
    ) -> Result<'a, JsLocal<'a>> {
        let global = heap.global_object();
        let entries = entries.into_iter();
        let (at_least, at_most) = entries.size_hint();
        let record = JSValue::create_empty_object(global, at_most.unwrap_or(at_least));
        for (key, value) in entries {
            let (key, value) = (key.as_ref(), convert(heap, value)?);
            // SAFETY: `record` is the object made above, and the key is read before this returns.
            crate::call_false_is_throw(global, || unsafe {
                extern_types::Bun__Bindgen__putRecordEntry(
                    global,
                    record,
                    key.as_ptr(),
                    key.len(),
                    value.0,
                )
            })
            .map_err(Error::pending)?;
        }
        Ok(JsLocal::from_raw(record))
    }

    /// An empty value is a member that is absent.
    ///
    /// # Safety
    /// `Tables::memberNames` names `values`, from `first_member_name_index`: the members of the returned dictionary number `dictionary_index`.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn object<'a>(
        heap: &JsHeap<'a>,
        first_member_name_index: u32,
        dictionary_index: u32,
        has_every_member: bool,
        values: &[JSValue],
    ) -> Result<'a, JsLocal<'a>> {
        // SAFETY: forwarded; this cannot throw.
        Ok(JsLocal::from_raw(unsafe {
            extern_types::Bun__Bindgen__createObject(
                heap.global_ptr(),
                first_member_name_index,
                dictionary_index,
                has_every_member,
                values.as_ptr(),
                values.len(),
            )
        }))
    }

    /// # Safety: as for [`object`].
    #[doc(hidden)]
    #[inline]
    pub unsafe fn null_prototype_object<'a>(
        heap: &JsHeap<'a>,
        first_member_name_index: u32,
        values: &[JSValue],
    ) -> Result<'a, JsLocal<'a>> {
        // SAFETY: forwarded; this cannot throw.
        Ok(JsLocal::from_raw(unsafe {
            extern_types::Bun__Bindgen__createNullPrototypeObject(
                heap.global_ptr(),
                first_member_name_index,
                values.as_ptr(),
                values.len(),
            )
        }))
    }

    /// # Safety
    /// `index` is one into `Tables::enumerationValues`.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn enumeration_value<'a>(heap: &JsHeap<'a>, index: u32) -> Result<'a, JsLocal<'a>> {
        // SAFETY: forwarded; this cannot throw.
        Ok(JsLocal::from_raw(unsafe {
            extern_types::Bun__Bindgen__enumerationValueToJS(heap.global_ptr(), index)
        }))
    }
}

#[doc(hidden)]
#[inline(always)]
pub fn host_fn_return<'a, T, E: IntoError<'a>>(
    cx: &mut JsScope<'a>,
    result: core::result::Result<T, E>,
    convert: impl FnOnce(&JsHeap<'a>, T) -> Result<'a, JsLocal<'a>>,
) -> JSValue {
    let value = 'value: {
        let error = match result {
            Ok(value) => match convert(&cx.heap, value) {
                Ok(value) => break 'value value.0,
                Err(error) => error,
            },
            Err(error) => error.into_error(&cx.heap),
        };
        error.into_host_fn_return(cx)
    };
    debug_assert!(
        cx.heap.exception_presence_matches(value.is_empty()),
        "a body fails exactly when an exception is pending",
    );
    value
}

/// As [`host_fn_return`], for the constructor of a `refCounted` class: null if it failed.
#[doc(hidden)]
#[inline(always)]
pub fn host_fn_construct_return<'a, T, E: IntoError<'a>>(
    cx: &mut JsScope<'a>,
    result: core::result::Result<*mut T, E>,
) -> *mut c_void {
    let wrapped: *mut c_void = match result {
        Ok(wrapped) => wrapped.cast(),
        Err(error) => {
            error.into_error(&cx.heap).into_host_fn_return(cx);
            core::ptr::null_mut()
        }
    };
    debug_assert!(
        cx.heap.exception_presence_matches(wrapped.is_null()),
        "a constructor fails exactly when an exception is pending",
    );
    wrapped
}
